type ImportedTaskSeed={title:string;notes?:string;section:Section;day?:string;done?:boolean};
const markdownSection=(heading:string,current:Section):{section:Section;day?:string}=>{
 const value=heading.toLowerCase().replace(/[^\w\s&-]/g,"").replace(/\s+/g," ").trim();
 const weekdays=["monday","tuesday","wednesday","thursday","friday","saturday","sunday"];
 const weekday=weekdays.find(day=>value===day||value.startsWith(`${day} `));
 if(weekday)return{section:"week",day:weekday[0].toUpperCase()+weekday.slice(1)};
 if(["today","now","one and done"].includes(value))return{section:"today"};
 if(["maintenance","daily maintenance","daily and weekly maintenance","patrols"].includes(value))return{section:"patrols"};
 if(["personal projects","projects"].includes(value))return{section:"projects"};
 if(["business","stottly","stottly enterprises"].includes(value))return{section:"stottly"};
 if(["business long term","long term business","business backlog"].includes(value))return{section:"businessLong"};
 if(["this week","week","weekly"].includes(value))return{section:"week"};
 if(["keep an eye on","watch","watch list"].includes(value))return{section:"watch"};
 if(["this month","month","monthly"].includes(value))return{section:"month"};
 if(["long term","personal long term"].includes(value))return{section:"long"};
 if(["quick notes","notes"].includes(value))return{section:"notes"};
 return{section:current};
};
const parseMarkdownTasks=(text:string):ImportedTaskSeed[]=>{
 const tasks:ImportedTaskSeed[]=[];
 let section:Section="today",day:string|undefined,last:ImportedTaskSeed|undefined;
 text.split(/\r?\n/).forEach(raw=>{
  const heading=raw.match(/^\s*#{1,6}\s+(.+?)\s*#*\s*$/);
  if(heading){const mapped=markdownSection(heading[1],section);section=mapped.section;day=mapped.day;last=undefined;return}
  const item=raw.match(/^\s*(?:[-*+]\s+(?:\[([ xX])\]\s+)?|\d+[.)]\s+)(.+?)\s*$/);
  if(item){
   const checked=item[1]?.toLowerCase()==="x",title=item[2].replace(/\s+<!--.*?-->\s*$/,"").trim();
   if(title){last={title,section,day,done:checked};tasks.push(last)}
   return;
  }
  const continuation=raw.trim();
  if(last&&continuation&&!/^[-*_]{3,}$/.test(continuation))last.notes=[last.notes,continuation].filter(Boolean).join("\n");
 });
 return tasks;
};
