const repeatLabel=(task:Task)=>{
 if(!task.recurring)return"";
 const interval=Math.max(1,Number(task.repeatInterval)||1),unit=task.repeatUnit||(task.recurringDays?.length?"week":"day");
 if(unit==="week"&&task.recurringDays?.length)return interval===1?`Every ${task.recurringDays.join(", ")}`:`Every ${interval} weeks · ${task.recurringDays.join(", ")}`;
 if(interval===1)return unit==="day"?"Every day":unit==="week"?"Every week":unit==="month"?"Every month":"Every year";
 if(unit==="week"&&interval===2)return"Every 2 weeks";
 return`Every ${interval} ${unit}s`;
};
